CREATE OR REPLACE FUNCTION public.flowmate_kpi_ai_tags(p_work_item_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_tags text[];
begin
  if to_regclass('public.work_item_ai_tags') is null then
    return '{}'::text[];
  end if;

  execute $query$
    select coalesce(array_agg(t.tag order by t.created_at, t.id), '{}'::text[])
    from public.work_item_ai_tags t
    where t.work_item_id = $1
  $query$ into v_tags using p_work_item_id;

  return coalesce(v_tags, '{}'::text[]);
end;
$function$

CREATE OR REPLACE FUNCTION public.flowmate_kpi_working_date_gap(p_started_on date, p_ended_on date, p_calendar_scope text DEFAULT 'all'::text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_days integer;
begin
  if p_started_on is null or p_ended_on is null then
    return null;
  end if;

  if p_calendar_scope not in ('all', 'gdve', 'requester') then
    raise exception 'Unsupported KPI calendar scope: %', p_calendar_scope;
  end if;

  if p_started_on = p_ended_on then
    return 0;
  end if;

  if p_ended_on > p_started_on then
    select count(*)::integer
    into v_days
    from pg_catalog.generate_series(
      p_started_on + 1,
      p_ended_on,
      interval '1 day'
    ) as day_slice(day_start)
    where extract(isodow from day_slice.day_start)::integer between 1 and 5
      and not exists (
        select 1
        from public.flowmate_non_working_days h
        where h.day = day_slice.day_start::date
          and h.active = true
          and (
            h.scope = 'all'
            or (p_calendar_scope = 'gdve' and h.scope = 'gdve')
          )
      );
    return v_days;
  end if;

  select count(*)::integer
  into v_days
  from pg_catalog.generate_series(
    p_ended_on + 1,
    p_started_on,
    interval '1 day'
  ) as day_slice(day_start)
  where extract(isodow from day_slice.day_start)::integer between 1 and 5
    and not exists (
      select 1
      from public.flowmate_non_working_days h
      where h.day = day_slice.day_start::date
        and h.active = true
        and (
          h.scope = 'all'
          or (p_calendar_scope = 'gdve' and h.scope = 'gdve')
        )
    );

  return -v_days;
end;
$function$

CREATE OR REPLACE FUNCTION public.flowmate_kpi_working_duration_days(p_started_at timestamp with time zone, p_ended_at timestamp with time zone, p_calendar_scope text DEFAULT 'all'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_started_local timestamp;
  v_ended_local timestamp;
  v_days numeric;
begin
  if p_started_at is null or p_ended_at is null then
    return null;
  end if;

  if p_calendar_scope not in ('all', 'gdve', 'requester') then
    raise exception 'Unsupported KPI calendar scope: %', p_calendar_scope;
  end if;

  if p_ended_at < p_started_at then
    return null;
  end if;

  v_started_local := p_started_at at time zone 'Asia/Bangkok';
  v_ended_local := p_ended_at at time zone 'Asia/Bangkok';

  select coalesce(sum(
    extract(epoch from (
      least(v_ended_local, day_slice.day_start + interval '1 day')
      - greatest(v_started_local, day_slice.day_start)
    )) / 86400.0
  ), 0)::numeric
  into v_days
  from pg_catalog.generate_series(
    date_trunc('day', v_started_local),
    date_trunc('day', v_ended_local),
    interval '1 day'
  ) as day_slice(day_start)
  where extract(isodow from day_slice.day_start)::integer between 1 and 5
    and not exists (
      select 1
      from public.flowmate_non_working_days h
      where h.day = day_slice.day_start::date
        and h.active = true
        and (
          h.scope = 'all'
          or (p_calendar_scope = 'gdve' and h.scope = 'gdve')
        )
    );

  return round(v_days, 6);
end;
$function$
